// =============================================================================
//  Sugarplum Hollow — world composition
//  A gingerbread village with a candy-cane fence, lollipop forest, jellybean
//  orchards, marshmallow drifts, gumdrop boulders, peppermint plaza and a
//  flowing chocolate river. 100% procedural: every vertex and every material
//  parameter below is generated by code from a seed.
// =============================================================================
import { Builder, box, cylinder, sphere, disc, tube, triPrism, ribbon, grid, vec } from './geo.js';
import { compose, mul, rotX, rotY, rotZ, translation, transformPoint, quatFromEuler, smoothstep, clamp } from './math.js';
import { MAT, PAL, mat, pick, mulberry32 } from './materials.js';

// ------------------------------------------------------------------ materials
const MB = {
  snow: mat(MAT.SNOW, { cast: false }),
  ginger: mat(MAT.GINGER, { c1: PAL.gingerLight, c2: PAL.gingerDark }),
  gingerDark: mat(MAT.GINGER, { c1: PAL.gingerMid, c2: PAL.gingerDark }),
  icing: mat(MAT.ICING, { c1: PAL.icing }),
  icingCream: mat(MAT.ICING, { c1: PAL.icingCream }),
  choc: mat(MAT.CHOC, { c1: PAL.chocLight, c2: PAL.chocDark }),
  chocDark: mat(MAT.CHOC, { c1: PAL.chocDark, c2: PAL.chocBlack }),
  cane: mat(MAT.CANE, { c1: PAL.caneRed }),
  caneMint: mat(MAT.CANE, { c1: PAL.caneMint }),
  lolli: mat(MAT.LOLLI, { c1: PAL.lolliPink, c2: PAL.lolliPurple }),
  lolliBlue: mat(MAT.LOLLI, { c1: PAL.lolliBlue, c2: PAL.lolliPurple }),
  lolliYel: mat(MAT.LOLLI, { c1: PAL.lolliYellow, c2: PAL.lolliPink }),
  jelly: mat(MAT.JELLY),
  mallow: mat(MAT.MALLOW),
  gum: mat(MAT.GUMDROP),
  peppermint: mat(MAT.PEPPERMINT, { c1: PAL.peppermint, c2: PAL.lolliPink }),
  glass: mat(MAT.GLASS, { c1: PAL.glass, em: 1.15 }),
  lampGlass: mat(MAT.GLASS, { c1: PAL.lolliYellow, em: 1.7 }),
  licorice: mat(MAT.LICORICE, { c1: PAL.licorice }),
  sprinkle: mat(MAT.SPRINKLE, { cast: false }),
  river: mat(MAT.RIVER, { c1: PAL.riverLight, c2: PAL.riverDark, cast: false }),
};

// ------------------------------------------------------------------- terrain
export function riverCenterZ(x) {
  return -(42 + Math.sin(x * 0.055) * 6.5 + Math.sin(x * 0.11 + 1.2) * 2.6);
}

export function groundHeight(x, z) {
  const r = Math.hypot(x, z);
  const hills = smoothstep(56, 118, r);
  const nd = Math.abs(z - riverCenterZ(x));
  const valley = smoothstep(10, 26, nd);
  const n =
    Math.sin(x * 0.055) * Math.cos(z * 0.061) * 3.2 +
    Math.sin(x * 0.12 + z * 0.098) * 1.5 +
    Math.cos(z * 0.17 - x * 0.081) * 1.1;
  return Math.max(hills * valley * (5.0 + n), 0);
}

// ------------------------------------------------------- instanced geometry
class InstSet {
  constructor() {
    this.list = [];
  }
  push(p, s, q, tint = [1, 1, 1, 1], hue = 0) {
    this.list.push({ p, s, q, tint, hue });
  }
  get length() {
    return this.list.length;
  }
}

// ------------------------------------------------------------- tiny helpers
function bez(a, b, c, t) {
  const u = 1 - t;
  return [
    u * u * a[0] + 2 * u * t * b[0] + t * t * c[0],
    u * u * a[1] + 2 * u * t * b[1] + t * t * c[1],
    u * u * a[2] + 2 * u * t * b[2] + t * t * c[2],
  ];
}

function canePath(x, y, z, height, hookDir, hookR, segs = 12) {
  const pts = [];
  const straight = height;
  for (let i = 0; i <= 4; i++) pts.push([x, y + (straight * i) / 4, z]);
  const cx = x + hookDir * hookR;
  const cy = y + straight;
  for (let i = 1; i <= segs; i++) {
    const a = Math.PI - (i / segs) * (Math.PI * 1.28);
    pts.push([cx + Math.cos(a) * hookR, cy + Math.sin(a) * hookR, z + Math.sin(a * 2) * 0.02]);
  }
  return pts;
}

// --------------------------------------------------------------------- house
function addWindow(B, I, o) {
  const { w = 1.15, h = 1.45, frameMat = MB.icing, R = Math.random } = o;
  B.push(compose([o.x, o.y, o.z], [0, o.rot || 0, 0], [1, 1, 1]));
  // Glowing sugar glass
  B.add(box(w, h, 0.06), MB.glass, { m: translation(0, 0, 0.03) });
  // Icing frame
  const t = 0.17;
  B.add(box(w + t * 2, t, 0.16), frameMat, { m: translation(0, h / 2 + t / 2, 0.1) });
  B.add(box(w + t * 2, t, 0.16), frameMat, { m: translation(0, -h / 2 - t / 2, 0.1) });
  B.add(box(t, h, 0.16), frameMat, { m: translation(-w / 2 - t / 2, 0, 0.1) });
  B.add(box(t, h, 0.16), frameMat, { m: translation(w / 2 + t / 2, 0, 0.1) });
  // Mullions
  B.add(box(0.07, h, 0.1), MB.icing, { m: translation(0, 0, 0.09) });
  B.add(box(w, 0.07, 0.1), MB.icing, { m: translation(0, h * 0.12, 0.09) });
  // Candy cane sill
  B.add(box(w + 0.62, 0.15, 0.4), MB.cane, { m: translation(0, -h / 2 - t - 0.06, 0.18) });
  // Little gumdrop window box
  const n = Math.max(2, Math.round(w / 0.42));
  for (let i = 0; i < n; i++) {
    const px = -w / 2 + 0.2 + (i / Math.max(1, n - 1)) * (w - 0.4);
    const p = transformPoint(B.M, [px, -h / 2 - t - 0.3, 0.34]);
    I.gum.push(
      p,
      [0.1, 0.12, 0.1],
      quatFromEuler(0, Math.random() * 6.28, 0),
      [...pick(PAL.gumdrop, R), 1],
    );
  }
  B.pop();
}

function addDoor(B, I, o) {
  const { w = 1.5, h = 2.25 } = o;
  B.push(compose([o.x, o.y, o.z], [0, o.rot || 0, 0], [1, 1, 1]));
  B.add(box(w, h, 0.16), MB.choc, { m: translation(0, 0, 0.05) });
  // Icing arch over the doorway
  const pts = [];
  for (let i = 0; i <= 10; i++) {
    const a = (i / 10) * Math.PI;
    pts.push([Math.cos(a) * (w / 2 + 0.12), h / 2 + 0.05 + Math.sin(a) * (w / 2 + 0.12), 0.14]);
  }
  B.add(tube(pts, 0.13, 7), MB.icing);
  // Door frames
  B.add(box(0.16, h + 0.1, 0.18), MB.icing, { m: translation(-w / 2 - 0.08, 0, 0.12) });
  B.add(box(0.16, h + 0.1, 0.18), MB.icing, { m: translation(w / 2 + 0.08, 0, 0.12) });
  // Door planks
  for (let i = 0; i < 4; i++) {
    B.add(box(0.06, h * 0.9, 0.04), MB.chocDark, { m: translation(-w * 0.33 + (i / 3) * w * 0.66, 0, 0.14), ao: 0.85 });
  }
  // Candy knob
  B.add(sphere(0.12, 10, 8), MB.cane, { m: translation(w * 0.3, -0.05, 0.22) });
  B.pop();
}

function addRoofSides(B, I, o) {
  const { w, d, eaveY, roofH, R } = o;
  const ovX = 0.85;
  const ovZ = 0.75;
  const halfD = d / 2 + ovZ;
  const ang = Math.atan2(roofH, halfD);
  const L = Math.hypot(roofH, halfD) + 0.35;
  const thick = 0.34;

  for (const s of [1, -1]) {
    const ridge = [0, eaveY + roofH, 0];
    const eave = [0, eaveY, s * halfD];
    const c = [0, (ridge[1] + eave[1]) / 2, (ridge[2] + eave[2]) / 2];
    const rot = s > 0 ? rotX(ang) : mul(rotY(Math.PI), rotX(ang));
    const slabM = mul(translation(c[0], c[1], c[2]), rot);
    B.add(box(w + ovX * 2, thick, L), MB.ginger, { m: slabM });
    // Icing "snow" blanket on top
    const icingM = mul(slabM, translation(0, thick / 2 + 0.11, 0.05));
    B.add(box(w + ovX * 2 - 0.12, 0.24, L * 0.94), MB.icing, { m: icingM, ao: 1.0 });
    // Drifting icing scallops along the eave
    const dripN = Math.round((w + ovX * 2) / 0.62);
    for (let i = 0; i <= dripN; i++) {
      const px = -(w / 2 + ovX) + (i / dripN) * (w + ovX * 2);
      const p = transformPoint(B.M, transformPoint(slabM, [px, thick / 2 + 0.1, L / 2 - 0.15]));
      const r = 0.13 + R() * 0.09;
      I.icing.push(p, [r, r * (1.1 + R() * 0.8), r], quatFromEuler(0, R() * 6.28, 0));
    }
    // Sprinkles scattered across the icing
    const sn = 46;
    for (let i = 0; i < sn; i++) {
      const px = (R() - 0.5) * (w + ovX * 1.7);
      const pz = (R() - 0.5) * L * 0.85;
      const p = transformPoint(B.M, transformPoint(icingM, [px, 0.13, pz]));
      I.sprinkle.push(
        p,
        [0.035, 0.035, 0.14 + R() * 0.06],
        quatFromEuler(R() * 1.2 - 0.6, R() * 6.28, R() * 1.2 - 0.6),
        [1, 1, 1, 1],
        R(),
      );
    }
    // Gumdrops perched along the eave
    const gdN = 5;
    for (let i = 0; i < gdN; i++) {
      const px = -(w / 2 + ovX) + 0.5 + R() * (w + ovX * 2 - 1.0);
      const p = transformPoint(B.M, transformPoint(slabM, [px, thick / 2 + 0.3, -L / 2 + 0.3 + R() * 0.5]));
      const sc = 0.11 + R() * 0.06;
      I.gum.push(p, [sc, sc * 1.35, sc], quatFromEuler(0, R() * 6.28, 0), [...pick(PAL.gumdrop, R), 1]);
    }
  }
}

/**
 * The star of the show: a gingerbread cottage with piped icing, candy canes,
 * glowing sugar windows and a chimney puffing marshmallow smoke.
 */
function addHouse(B, I, R, o) {
  const {
    x = 0,
    z = 0,
    rot = 0,
    w = 9,
    d = 8,
    h = 5,
    roofH = 3.4,
    wall = MB.ginger,
    foundation = MB.choc,
    windows = 2,
  } = o;

  B.push(compose([x, 0, z], [0, rot, 0], [1, 1, 1]));

  const eaveY = 0.55 + h;

  // Foundation slab
  B.add(box(w + 0.9, 0.55, d + 0.9), foundation, { m: translation(0, 0.275, 0) });
  B.add(box(w + 1.2, 0.16, d + 1.2), MB.icing, { m: translation(0, 0.06, 0), ao: 0.9 });

  // Walls
  B.add(box(w, h, d), wall, { m: translation(0, 0.55 + h / 2, 0) });

  // Piped icing corner posts
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      B.add(cylinder(0.26, 0.24, h, 8), MB.icing, {
        m: translation(sx * (w / 2 - 0.02), 0.55, sz * (d / 2 - 0.02)),
      });
      B.add(sphere(0.3, 10, 8), MB.icing, { m: translation(sx * (w / 2 - 0.02), 0.55, sz * (d / 2 - 0.02)) });
    }
  }

  // Icing band around the top of the walls
  B.add(box(w + 0.34, 0.3, d + 0.34), MB.icing, { m: translation(0, eaveY - 0.12, 0) });

  // Gable
  B.add(triPrism(w, roofH, d), wall, { m: translation(0, eaveY, 0) });

  addRoofSides(B, I, { w, d, eaveY, roofH, R });

  // Ridge gumdrops
  const ridgeN = Math.round(w / 0.75);
  for (let i = 0; i <= ridgeN; i++) {
    const px = -w / 2 + (i / ridgeN) * w;
    const p = transformPoint(B.M, [px, eaveY + roofH + 0.32, 0]);
    const sc = 0.14 + R() * 0.07;
    I.gum.push(p, [sc, sc * 1.4, sc], quatFromEuler(0, R() * 6.28, 0), [...pick(PAL.gumdrop, R), 1]);
  }

  // Front windows
  const frontZ = d / 2;
  const wz = frontZ + 0.02;
  if (windows >= 1) {
    for (const sx of [-1, 1]) {
      addWindow(B, I, { x: sx * (w * 0.3), y: 0.55 + h * 0.55, z: wz, w: 1.25, h: 1.5, R });
    }
  }
  if (windows >= 3) {
    addWindow(B, I, { x: 0, y: 0.55 + h * 0.55, z: -frontZ - 0.02, rot: Math.PI, w: 1.25, h: 1.5, R });
  }
  // Side windows
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      addWindow(B, I, {
        x: sx * (w / 2 + 0.02),
        y: 0.55 + h * 0.55,
        z: sz * d * 0.22,
        rot: sx > 0 ? Math.PI / 2 : -Math.PI / 2,
        w: 1.0,
        h: 1.3,
        R,
      });
    }
  }

  // Door + porch
  addDoor(B, I, { x: 0, y: 0.55 + 1.15, z: frontZ + 0.04, w: 1.5, h: 2.3 });
  B.add(box(3.6, 0.32, 1.7), MB.icing, { m: translation(0, 0.7, frontZ + 0.85) });
  for (const sx of [-1, 1]) {
    B.add(tube(canePath(sx * 1.5, 0.86, frontZ + 1.5, 2.1, -sx, 0.24, 8), 0.11, 7), MB.cane);
  }
  B.add(box(3.9, 0.24, 2.3), MB.icing, { m: mul(translation(0, 3.2, frontZ + 0.95), rotX(0.1)) });
  // Lollipops flanking the door
  for (const sx of [-1, 1]) {
    B.add(cylinder(0.055, 0.055, 1.3, 6), MB.cane, { m: translation(sx * 2.35, 0.55, frontZ + 0.55) });
    B.add(disc(0.34, 18, 0.1), MB.lolli, {
      m: mul(translation(sx * 2.35, 1.95, frontZ + 0.55), rotX(Math.PI / 2)),
    });
  }

  // Chimney with marshmallow smoke
  const chX = w * 0.32;
  const chZ = -d * 0.22;
  const chH = roofH * 0.8 + 1.4;
  B.add(box(0.8, chH, 0.8), wall, { m: translation(chX, eaveY + 0.3, chZ) });
  B.add(box(1.0, 0.2, 1.0), MB.icing, { m: translation(chX, eaveY + 0.3 + chH, chZ) });
  for (let i = 0; i < 5; i++) {
    const t = i / 4;
    const p = transformPoint(B.M, [chX + Math.sin(i * 1.9) * 0.42 * t, eaveY + 0.35 + chH + t * 1.35, chZ + Math.cos(i * 1.3) * 0.3 * t]);
    const s = 0.16 + t * 0.26;
    I.mallow.push(p, [s, s * 0.88, s], quatFromEuler(0, R() * 6.28, 0));
  }

  // Icicle candy hanging from the eaves
  for (const sz of [-1, 1]) {
    const n = Math.round(w / 0.9);
    for (let i = 0; i <= n; i++) {
      if (R() > 0.55) continue;
      const px = -w / 2 + (i / n) * w;
      const len = 0.25 + R() * 0.42;
      B.add(cylinder(0.07, 0.0, len, 6), MB.caneMint, {
        m: mul(translation(px, eaveY - 0.3, sz * (d / 2 + 0.12)), rotX(Math.PI)),
      });
    }
  }

  B.pop();
}

// ------------------------------------------------------------------- trees
function addLollipopTree(B, I, R, o) {
  const { x, y0, z, height } = o;
  const lean = (R() - 0.5) * 0.16;
  const phase = R() * 6.28;
  const pts = [];
  const segs = 5;
  for (let i = 0; i <= segs; i++) {
    const t = i / segs;
    pts.push([x + Math.sin(phase) * lean * t * 2, y0 + t * height, z + Math.cos(phase) * lean * t * 2]);
  }
  B.add(tube(pts, (t) => 0.19 - t * 0.05, 7), R() > 0.5 ? MB.cane : MB.chocDark);

  const r = 1.5 + R() * 1.35;
  const face = R() * 6.28;
  const tip = pts[segs];
  const m = mul(
    translation(tip[0], tip[1] + r * 0.55, tip[2]),
    mul(rotY(face), mul(rotX(Math.PI / 2 + (R() - 0.5) * 0.5), rotZ(R() * 6.28))),
  );
  B.add(disc(r, 30, 0.22), R() > 0.72 ? MB.lolliBlue : R() > 0.45 ? MB.lolli : MB.lolliYel, { m });
  // a smaller candy disc peeking out behind it
  if (R() > 0.55) {
    B.add(disc(r * 0.6, 22, 0.18), MB.lolliYel, {
      m: mul(translation(tip[0], tip[1] + r * 0.35, tip[2] - 0.35), mul(rotY(face + 0.9), rotX(Math.PI / 2))),
    });
  }
  // jellybeans clinging to the lollipop's edge
  for (let i = 0; i < 4; i++) {
    const a = R() * 6.28;
    const rr = r * (0.7 + R() * 0.25);
    const p = transformPoint(m, [Math.cos(a) * rr, 0.16, Math.sin(a) * rr]);
    I.jelly.push(p, [0.14, 0.11, 0.1], quatFromEuler(R() * 3, R() * 3, 0), [...pick(PAL.jelly, R), 1]);
  }
}

function addJellyTree(B, I, R, o) {
  const { x, y0, z, height } = o;
  // chocolate trunk
  B.add(cylinder(0.34, 0.18, height, 9), MB.chocDark, { m: translation(x, y0, z) });
  B.add(sphere(0.36, 10, 8), MB.choc, { m: translation(x, y0 + 0.08, z) });

  const branches = 5 + Math.floor(R() * 3);
  const topY = y0 + height;
  for (let b = 0; b < branches; b++) {
    const a = (b / branches) * 6.28 + R() * 0.8;
    const startY = y0 + height * (0.55 + R() * 0.38);
    const start = [x, startY, z];
    const len = 2.2 + R() * 2.2;
    const dirV = vec.norm([Math.cos(a), 0.42 + R() * 0.5, Math.sin(a)]);
    const end = vec.add(start, vec.scale(dirV, len));
    const mid = vec.add(vec.lerp(start, end, 0.5), [0, 0.35 + R() * 0.4, 0]);
    const pts = [];
    for (let i = 0; i <= 6; i++) pts.push(bez(start, mid, end, i / 6));
    B.add(tube(pts, (t) => 0.11 - t * 0.045, 6), MB.chocDark);

    // Jellybean fruit clusters hanging off the branch
    const clusters = 3 + Math.floor(R() * 2);
    for (let c = 0; c < clusters; c++) {
      const t = 0.45 + (c / Math.max(1, clusters - 1)) * 0.5;
      const p = bez(start, mid, end, Math.min(t, 0.98));
      const n = 2 + Math.floor(R() * 3);
      for (let i = 0; i < n; i++) {
        const drop = 0.12 + R() * 0.12;
        const jp = [p[0] + (R() - 0.5) * 0.32, p[1] - drop, p[2] + (R() - 0.5) * 0.32];
        const s = 0.155 + R() * 0.095;
        I.jelly.push(
          jp,
          [s * 1.22, s * 0.95, s * 0.8],
          quatFromEuler(R() * 0.7, R() * 6.28, R() * 0.7),
          [...pick(PAL.jelly, R), 1],
        );
      }
      // a thread of icing sugar holding the fruit
      B.add(tube([p, [p[0], p[1] - 0.16, p[2]]], 0.018, 4, { capStart: false, capEnd: false }), MB.icing);
    }
  }

  // Crown of beans on top
  for (let i = 0; i < 5; i++) {
    const a = R() * 6.28;
    const s = 0.14 + R() * 0.07;
    I.jelly.push(
      [x + Math.cos(a) * 0.35, topY + 0.1 + R() * 0.25, z + Math.sin(a) * 0.35],
      [s * 1.2, s, s * 0.8],
      quatFromEuler(R() * 0.6, R() * 6.28, R() * 0.6),
      [...pick(PAL.jelly, R), 1],
    );
  }
}

function addCaneCluster(B, I, R, o) {
  const { x, y0, z } = o;
  const n = 2 + Math.floor(R() * 4);
  for (let i = 0; i < n; i++) {
    const a = R() * 6.28;
    const rr = R() * 1.1;
    const hgt = 2.4 + R() * 3.4;
    const face = R() * 6.28;
    const m = i % 2 === 0 ? MB.cane : R() > 0.5 ? MB.caneMint : MB.cane;
    B.push(compose([x + Math.cos(a) * rr, y0, z + Math.sin(a) * rr], [0, face, 0], [1, 1, 1]));
    B.add(tube(canePath(0, 0, 0, hgt, 1, 0.42 + R() * 0.3, 10), 0.115 + R() * 0.05, 7), m);
    B.pop();
  }
}

// ------------------------------------------------------------------ scene bits
function addLamppost(B, I, R, x, z, y0) {
  B.push(compose([x, y0, z], [0, R() * 6.28, 0], [1, 1, 1]));
  B.add(box(0.7, 0.22, 0.7), MB.choc, { m: translation(0, 0.11, 0) });
  B.add(tube(canePath(0, 0.18, 0, 3.9, 1, 0.3, 10), 0.085, 7), MB.cane);
  // glowing lollipop lamp
  B.add(disc(0.62, 26, 0.26), MB.lampGlass, { m: mul(translation(0, 4.55, 0), mul(rotY(0), rotX(Math.PI / 2))) });
  B.add(cylinder(0.2, 0.06, 0.2, 8), MB.icing, { m: translation(0, 4.2, 0) });
  B.pop();
}

function addSnowman(B, I, R, x, z, y0) {
  const s = 0.9 + R() * 0.35;
  B.push(compose([x, y0, z], [0, R() * 6.28, 0], [s, s, s]));
  B.add(sphere(0.85, 16, 12), MB.mallow, { m: translation(0, 0.62, 0) });
  B.add(sphere(0.62, 16, 12), MB.mallow, { m: translation(0, 1.72, 0) });
  B.add(sphere(0.45, 16, 12), MB.mallow, { m: translation(0, 2.52, 0) });
  // gumdrop buttons + eyes + nose
  for (let i = 0; i < 3; i++) {
    B.add(sphere(0.09, 8, 6), MB.gum, {
      m: translation(0, 1.9 - i * 0.34, 0.55 - i * 0.03),
      variant: R(),
    });
  }
  B.add(sphere(0.075, 8, 6), MB.licorice, { m: translation(-0.16, 2.62, 0.4) });
  B.add(sphere(0.075, 8, 6), MB.licorice, { m: translation(0.16, 2.62, 0.4) });
  B.add(cylinder(0.09, 0.0, 0.42, 7), MB.lolliYel, { m: mul(translation(0, 2.5, 0.42), rotX(Math.PI / 2)) });
  // licorice arms
  for (const sx of [-1, 1]) {
    B.add(tube(
      [[sx * 0.5, 1.8, 0], [sx * 1.0, 2.05, 0.1], [sx * 1.35, 2.25, 0.05]],
      0.055, 5,
    ), MB.licorice);
  }
  // candy cane hat
  B.add(cylinder(0.34, 0.34, 0.1, 12), MB.cane, { m: translation(0, 2.86, 0) });
  B.add(cylinder(0.24, 0.24, 0.42, 12), MB.cane, { m: translation(0, 2.94, 0) });
  B.add(sphere(0.12, 8, 6), MB.icing, { m: translation(0, 3.4, 0) });
  B.pop();
}

function addMarshmallowDrift(B, I, R, x, z, spread, count, y0) {
  for (let i = 0; i < count; i++) {
    const a = R() * 6.28;
    const rr = R() * spread;
    const px = x + Math.cos(a) * rr;
    const pz = z + Math.sin(a) * rr;
    const s = 0.34 + R() * 0.62;
    I.mallow.push(
      [px, y0 + s * 0.34, pz],
      [s, s * (0.66 + R() * 0.3), s],
      quatFromEuler(R() * 0.25, R() * 6.28, R() * 0.25),
    );
  }
}

function addGumdropRocks(B, I, R, x, z, count, y0) {
  for (let i = 0; i < count; i++) {
    const a = R() * 6.28;
    const rr = R() * 2.6;
    const s = 0.22 + R() * 0.55;
    I.gum.push(
      [x + Math.cos(a) * rr, y0 + s * 0.5, z + Math.sin(a) * rr],
      [s, s * (1.0 + R() * 0.5), s],
      quatFromEuler(R() * 0.4, R() * 6.28, R() * 0.4),
      [...pick(PAL.gumdrop, R), 1],
    );
  }
}

function addFence(B, I, R, path, y0, o = {}) {
  const postH = o.postH ?? 1.15;
  const spacing = o.spacing ?? 2.0;
  const mats = [MB.cane, MB.caneMint];
  let acc = 0;
  let prev = null;
  for (let i = 0; i < path.length - 1; i++) {
    const a = path[i];
    const b = path[i + 1];
    const segLen = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const n = Math.max(1, Math.round(segLen / spacing));
    for (let k = 0; k < n; k++) {
      const t = k / n;
      const px = a[0] + (b[0] - a[0]) * t;
      const pz = a[1] + (b[1] - a[1]) * t;
      const p = [px, y0 + postH / 2, pz];
      if (prev) {
        for (const ry of [-postH * 0.30, postH * 0.30]) {
          B.add(
            tube([[prev[0], prev[1] + ry, prev[2]], [px, y0 + postH / 2 + ry, pz]], 0.072, 6),
            mats[1],
          );
        }
      }
      B.add(cylinder(0.105, 0.105, postH, 8), mats[0], { m: translation(px, y0, pz) });
      B.add(sphere(0.16, 10, 8), mats[0], { m: translation(px, y0 + postH, pz) });
      prev = p;
      acc += spacing;
    }
  }
  // final post
  const last = path[path.length - 1];
  B.add(cylinder(0.105, 0.105, postH, 8), mats[0], { m: translation(last[0], y0, last[1]) });
  B.add(sphere(0.16, 10, 8), mats[0], { m: translation(last[0], y0 + postH, last[1]) });
  return acc;
}

function addRiver(B, I, R) {
  const pts = []
  for (let x = -95; x <= 95; x += 2.5) {
    pts.push([x, [x, 0.08, riverCenterZ(x)]]);
  }
  B.add(ribbon(pts, [0, 0, 1], 8.6), MB.river);

  // Marshmallow banks hiding the seam where the chocolate meets the snow
  for (const s of [-1, 1]) {
    for (let x = -92; x <= 92; x += 2.6) {
      if (R() > 0.72) continue;
      const z = riverCenterZ(x) + s * (4.7 + R() * 0.9);
      const sc = 0.42 + R() * 0.62;
      I.mallow.push(
        [x + (R() - 0.5) * 1.4, sc * 0.3, z],
        [sc * 1.15, sc * 0.62, sc],
        quatFromEuler(0, R() * 6.28, 0),
      );
    }
  }
}

function addBridge(B, I, R, x) {
  const zc = riverCenterZ(x);
  const span = 7.6;
  const rise = 1.5;
  const n = 12;
  const deckMats = MB.gingerDark;
  const deck = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const z = zc - span + t * span * 2;
    const y = 0.35 + Math.sin(t * Math.PI) * rise;
    deck.push([z, y]);
  }
  for (let i = 0; i < n; i++) {
    const [z0, y0] = deck[i];
    const [z1, y1] = deck[i + 1];
    const cz = (z0 + z1) / 2;
    const cy = (y0 + y1) / 2;
    const ang = Math.atan2(y1 - y0, z1 - z0);
    const len = Math.hypot(z1 - z0, y1 - y0) * 1.12;
    B.add(box(3.4, 0.22, len), deckMats, { m: mul(translation(x, cy, cz), rotX(-ang)) });
  }
  // Icing rails + candy cane posts
  for (const sx of [-1, 1]) {
    const rp = deck.map(([z, y]) => [x + sx * 1.55, y + 1.0, z]);
    B.add(tube(rp, 0.075, 6), MB.icing);
    const rp2 = deck.map(([z, y]) => [x + sx * 1.55, y + 0.5, z]);
    B.add(tube(rp2, 0.06, 6), MB.caneMint);
    for (let i = 0; i <= 4; i++) {
      const idx = Math.round((i / 4) * n);
      const [z, y] = deck[idx];
      B.add(cylinder(0.06, 0.06, 1.0, 6), MB.cane, { m: translation(x + sx * 1.55, y, z) });
      B.add(sphere(0.1, 8, 6), MB.cane, { m: translation(x + sx * 1.55, y + 1.0, z) });
    }
  }
  // Marshmallow bollards at each end
  for (const sz of [-1, 1]) {
    for (const sx of [-1, 1]) {
      const p = [x + sx * 1.9, 0.45, zc + sz * (span + 0.5)];
      I.mallow.push(p, [0.5, 0.55, 0.5], quatFromEuler(0, R() * 6.28, 0));
      I.gum.push(
        [x + sx * 1.9, 1.05, zc + sz * (span + 0.5)],
        [0.16, 0.2, 0.16],
        quatFromEuler(0, R() * 6.28, 0),
        [...pick(PAL.gumdrop, R), 1],
      );
    }
  }
}

function addCandyArch(B, I, R, x, z, halfW, height) {
  // One continuous tube: up the left post, over the arc, down the right post.
  const pts = [];
  pts.push([x - halfW, 0, z]);
  pts.push([x - halfW, height * 0.6, z]);
  for (let i = 0; i <= 14; i++) {
    const a = Math.PI - (i / 14) * Math.PI;
    pts.push([x + Math.cos(a) * halfW, height + Math.sin(a) * halfW * 0.82, z]);
  }
  pts.push([x + halfW, height * 0.6, z]);
  pts.push([x + halfW, 0, z]);
  B.add(tube(pts, 0.24, 12), MB.cane);
  // second, thinner cane twisted alongside
  B.add(tube(pts.map((p) => [p[0], p[1] + 0.42, p[2] + 0.28]), 0.11, 8), MB.caneMint);
  // gumdrops + sprinkles along the arch
  for (let i = 0; i <= 16; i++) {
    const a = Math.PI - (i / 16) * Math.PI;
    const px = x + Math.cos(a) * halfW;
    const py = height + Math.sin(a) * halfW * 0.82;
    if (i % 2 === 0) {
      const sc = 0.13 + R() * 0.07;
      I.gum.push([px, py + 0.3, z], [sc, sc * 1.35, sc], quatFromEuler(0, R() * 6.28, 0), [...pick(PAL.gumdrop, R), 1]);
    }
    if (R() > 0.55) {
      I.sprinkle.push([px, py + 0.16, z], [0.03, 0.03, 0.12], quatFromEuler(R(), R() * 6.28, R()), [1, 1, 1, 1], R());
    }
  }
  // marshmallow footings
  for (const sx of [-1, 1]) {
    I.mallow.push([x + sx * halfW, 0.3, z], [0.55, 0.42, 0.55], quatFromEuler(0, R() * 6.28, 0));
  }
}

function addStringLights(B, I, R, a, b, sag = 1.2, count = 14) {
  const pts = [];
  for (let i = 0; i <= 20; i++) {
    const t = i / 20;
    const x = a[0] + (b[0] - a[0]) * t;
    const y = a[1] + (b[1] - a[1]) * t - Math.sin(t * Math.PI) * sag;
    const z = a[2] + (b[2] - a[2]) * t;
    pts.push([x, y, z]);
  }
  B.add(tube(pts, 0.018, 4, { capStart: false, capEnd: false }), MB.licorice);
  for (let i = 0; i < count; i++) {
    const t = (i + 0.5) / count;
    const x = a[0] + (b[0] - a[0]) * t;
    const y = a[1] + (b[1] - a[1]) * t - Math.sin(t * Math.PI) * sag;
    const z = a[2] + (b[2] - a[2]) * t;
    I.light.push([x, y - 0.1, z], [0.085, 0.11, 0.085], quatFromEuler(0, R() * 6.28, 0));
  }
}

// =============================================================== build world
export function buildWorld(seed = 20251224) {
  const B = new Builder();
  const R = mulberry32(seed);
  const I = {
    jelly: new InstSet(),
    gum: new InstSet(),
    sprinkle: new InstSet(),
    mallow: new InstSet(),
    icing: new InstSet(),
    puck: new InstSet(),
    light: new InstSet(),
    dust: new InstSet(),
  };

  // ---- reusable instanced primitives
  B.base('sphere', sphere(1, 14, 10));
  B.base('bean', sphere(1, 10, 7));
  B.base('puck', disc(1, 20, 0.22));
  B.base('sprinkle', sphere(1, 8, 6));
  B.base('dust', sphere(1, 6, 4));

  // ---- ground -------------------------------------------------------------
  B.add(grid(520, 128, groundHeight), MB.snow, { cast: false });

  // ---- peppermint plaza ---------------------------------------------------
  const PLAZA = { x: 0, z: 3.0, r: 7.6 };
  B.add(disc(PLAZA.r, 84, 0.3), MB.peppermint, { m: translation(PLAZA.x, 0.14, PLAZA.z) });
  // gumdrop border
  const borderN = 54;
  for (let i = 0; i < borderN; i++) {
    const a = (i / borderN) * 6.28;
    const sc = 0.13 + R() * 0.09;
    I.gum.push(
      [PLAZA.x + Math.cos(a) * (PLAZA.r + 0.2), 0.2, PLAZA.z + Math.sin(a) * (PLAZA.r + 0.2)],
      [sc, sc * 1.3, sc],
      quatFromEuler(0, R() * 6.28, 0),
      [...pick(PAL.gumdrop, R), 1],
    );
  }
  // peppermint stepping stones from the plaza up to the front door
  for (let i = 0; i < 5; i++) {
    const s2 = 0.56 + R() * 0.14;
    I.puck.push([(R() - 0.5) * 0.4, 0.16, -5.0 - i * 0.62], [s2, 1, s2], quatFromEuler(0, R() * 6.28, 0));
  }
  // and a loose ring of them around the plaza
  for (let i = 0; i < 24; i++) {
    const a = (i / 24) * 6.28 + 0.2;
    const rr = PLAZA.r + 1.4 + R() * 1.8;
    const px = PLAZA.x + Math.cos(a) * rr;
    const pz = PLAZA.z + Math.sin(a) * rr;
    const s2 = 0.46 + R() * 0.2;
    I.puck.push([px, groundHeight(px, pz) + 0.12, pz], [s2, 1, s2], quatFromEuler(0, R() * 6.28, 0));
  }

  // ---- the village --------------------------------------------------------
  addHouse(B, I, R, { x: 0, z: -14.5, rot: 0, w: 9.4, d: 8.2, h: 5.2, roofH: 3.6, windows: 2 });
  addHouse(B, I, R, { x: -19.0, z: -9.0, rot: 0.46, w: 7.2, d: 6.6, h: 4.2, roofH: 2.8, windows: 1, wall: MB.gingerDark });
  addHouse(B, I, R, { x: 18.0, z: -17.0, rot: -0.34, w: 8.0, d: 7.0, h: 4.6, roofH: 3.1, windows: 3 });
  addHouse(B, I, R, { x: 24.0, z: 10.5, rot: -1.9, w: 6.4, d: 6.0, h: 3.8, roofH: 2.5, windows: 1, wall: MB.gingerDark });

  // ---- entrance gateway, fences and lamps ---------------------------------
  addCandyArch(B, I, R, 0, 12.6, 2.9, 3.6);
  addCandyArch(B, I, R, -4, -33.0, 2.2, 2.9);

  addFence(B, I, R, [[-9.8, -7.6], [-9.8, -21.5], [-3.4, -21.5]], 0);
  addFence(B, I, R, [[3.4, -21.5], [9.8, -21.5], [9.8, -7.6]], 0);
  addFence(B, I, R, [[-9.8, -7.6], [-3.6, -7.6]], 0);
  addFence(B, I, R, [[3.6, -7.6], [9.8, -7.6]], 0);

  addLamppost(B, I, R, -11.5, 6.5, 0);
  addLamppost(B, I, R, 11.5, 6.5, 0);
  addLamppost(B, I, R, -11.5, -4.0, 0);
  addLamppost(B, I, R, 11.5, -4.0, 0);
  addLamppost(B, I, R, -15.0, 17.0, groundHeight(-15.0, 17.0));
  addLamppost(B, I, R, 15.5, 19.5, groundHeight(15.5, 19.5));

  // festoon lights slung between the plaza lampposts
  addStringLights(B, I, R, [-11.5, 4.6, 6.5], [-11.5, 4.6, -4.0], 0.9, 11);
  addStringLights(B, I, R, [11.5, 4.6, 6.5], [11.5, 4.6, -4.0], 0.9, 11);
  addStringLights(B, I, R, [-11.5, 4.6, 6.5], [11.5, 4.6, 6.5], 1.6, 14);

  // ---- snowmen + marshmallow drifts --------------------------------------
  addSnowman(B, I, R, 7.5, 10.5, 0);
  addSnowman(B, I, R, -9.0, 14.0, 0);
  addSnowman(B, I, R, 21.0, 2.0, 0);

  addMarshmallowDrift(B, I, R, 0, 18.0, 6.0, 15, 0);
  addMarshmallowDrift(B, I, R, -23, 9, 5.0, 12, 0);
  addMarshmallowDrift(B, I, R, 27, -5, 5.0, 12, 0);
  addMarshmallowDrift(B, I, R, -6, 27, 6.5, 13, 0);
  addMarshmallowDrift(B, I, R, 15, 29, 6.0, 12, 0);
  addMarshmallowDrift(B, I, R, -31, -16, 6.0, 13, groundHeight(-31, -16));

  // ---- gumdrop boulders ---------------------------------------------------
  addGumdropRocks(B, I, R, -13, 4, 6, 0);
  addGumdropRocks(B, I, R, 13, 4, 6, 0);
  addGumdropRocks(B, I, R, -5, 22, 7, 0);
  addGumdropRocks(B, I, R, 9, 22, 7, 0);
  addGumdropRocks(B, I, R, -25, -20, 8, 0);
  addGumdropRocks(B, I, R, 26, 22, 8, 0);

  // ---- chocolate river + bridge ------------------------------------------
  addRiver(B, I, R);
  addBridge(B, I, R, -4);

  // ---- candy forest -------------------------------------------------------
  const trees = [];
  const tryPlace = (x, z) => {
    const r = Math.hypot(x, z);
    if (r < 24) return false;
    if (Math.abs(z - riverCenterZ(x)) < 7.5) return false;
    for (const t of trees) {
      if (Math.hypot(t.x - x, t.z - z) < 4.3) return false;
    }
    return true;
  };

  let attempts = 0;
  while (trees.length < 210 && attempts < 9000) {
    attempts++;
    const a = R() * 6.28;
    const rr = 23 + Math.pow(R(), 0.72) * 72;
    const x = Math.cos(a) * rr;
    const z = Math.sin(a) * rr;
    if (!tryPlace(x, z)) continue;
    const y0 = groundHeight(x, z);
    const kind = R();
    if (kind < 0.36) {
      addJellyTree(B, I, R, { x, y0, z, height: 3.8 + R() * 3.0 });
      trees.push({ x, z, kind: 'jelly' });
    } else if (kind < 0.76) {
      addLollipopTree(B, I, R, { x, y0, z, height: 3.4 + R() * 3.6 });
      trees.push({ x, z, kind: 'lolli' });
    } else {
      addCaneCluster(B, I, R, { x, y0, z });
      trees.push({ x, z, kind: 'cane' });
    }
  }

  // Sugar-snow lumps so the drifts read as powder rather than a flat plane
  for (let i = 0; i < 900; i++) {
    const a = R() * 6.28;
    const rr = Math.pow(R(), 0.6) * 105;
    const x = Math.cos(a) * rr;
    const z = Math.sin(a) * rr;
    const s2 = 0.12 + R() * 0.34;
    I.dust.push(
      [x, groundHeight(x, z) - s2 * 0.28, z],
      [s2 * (1.1 + R() * 0.6), s2 * 0.55, s2 * (1.1 + R() * 0.6)],
      quatFromEuler(0, R() * 6.28, 0),
    );
  }

  // little piles of jellybeans dropped around the village
  for (let i = 0; i < 16; i++) {
    const a = R() * 6.28;
    const rr = 9 + R() * 12;
    const cx = Math.cos(a) * rr;
    const cz = Math.sin(a) * rr + 3;
    const n = 3 + Math.floor(R() * 4);
    for (let k = 0; k < n; k++) {
      const s2 = 0.12 + R() * 0.06;
      I.jelly.push(
        [cx + (R() - 0.5) * 0.7, s2 * 0.7, cz + (R() - 0.5) * 0.7],
        [s2 * 1.25, s2 * 0.95, s2 * 0.85],
        quatFromEuler(R() * 0.5, R() * 6.28, R() * 0.5),
        [...pick(PAL.jelly, R), 1],
      );
    }
  }

  // Fallen jellybeans scattered through the forest
  for (let i = 0; i < 240; i++) {
    const a = R() * 6.28;
    const rr = 22 + R() * 78;
    const x = Math.cos(a) * rr;
    const z = Math.sin(a) * rr;
    if (Math.abs(z - riverCenterZ(x)) < 6) continue;
    const s = 0.11 + R() * 0.07;
    I.jelly.push(
      [x, groundHeight(x, z) + s * 0.5, z],
      [s * 1.3, s * 0.9, s * 0.85],
      quatFromEuler(R() * 0.4, R() * 6.28, R() * 0.4),
      [...pick(PAL.jelly, R), 1],
    );
  }

  // A few lollipops lining the path to the bridge
  for (let i = 0; i < 5; i++) {
    addLollipopTree(B, I, R, { x: -4 + (i % 2 === 0 ? -3.4 : 3.4), y0: 0, z: -22 - i * 3.6, height: 2.9 + R() * 1.4 });
  }

  // ---- flush instanced sets into the shared instance buffer ----------------
  const instData = [];
  const emit = (set, baseName, material) => {
    if (!set.length) return;
    const start = instData.length / 16;
    for (const it of set.list) {
      instData.push(
        it.p[0], it.p[1], it.p[2], 0,
        it.s[0], it.s[1], it.s[2], it.hue,
        it.q[0], it.q[1], it.q[2], it.q[3],
        it.tint[0], it.tint[1], it.tint[2], it.tint[3],
      );
    }
    B.addInstanced(baseName, material, start, set.length);
  };

  emit(I.jelly, 'bean', MB.jelly);
  emit(I.gum, 'sphere', MB.gum);
  emit(I.sprinkle, 'sprinkle', MB.sprinkle);
  emit(I.mallow, 'sphere', MB.mallow);
  emit(I.icing, 'sphere', MB.icing);
  emit(I.puck, 'puck', MB.peppermint);
  emit(I.light, 'sphere', MB.lampGlass);
  emit(I.dust, 'dust', MB.mallow);

  const built = B.build();
  const draws = compactDraws(built, built.bases);

  return {
    ...built,
    draws,
    instances: new Float32Array(instData),
    instanceCount: instData.length / 16,
    stats: {
      vertices: built.vertexCount,
      triangles: built.triangleCount,
      draws: draws.length,
      instances: instData.length / 16,
    },
  };
}

/**
 * Merge all static draws that share a material into one big index range each.
 * Instanced draws reference the shared base-primitive ranges, so those are
 * copied first and their ranges (and the draws pointing at them) are remapped.
 */
function compactDraws(res, bases) {
  const newIndices = new Uint32Array(res.indices.length);
  let cursor = 0;

  // 1) Base primitives keep their own contiguous block at the front.
  const baseRemap = new Map();
  for (const name of Object.keys(bases)) {
    const b = bases[name];
    const oldFirst = b.firstIndex;
    newIndices.set(res.indices.subarray(oldFirst, oldFirst + b.indexCount), cursor);
    baseRemap.set(oldFirst, cursor);
    b.firstIndex = cursor;
    cursor += b.indexCount;
  }

  // 2) Static draws, grouped by material.
  const groups = new Map();
  const instanced = [];
  for (const d of res.draws) {
    if (d.useInstance) {
      instanced.push({ ...d, firstIndex: baseRemap.get(d.firstIndex) });
      continue;
    }
    let g = groups.get(d.key);
    if (!g) {
      g = { proto: d, ranges: [] };
      groups.set(d.key, g);
    }
    g.ranges.push([d.firstIndex, d.indexCount]);
  }

  const out = [];
  for (const g of groups.values()) {
    const start = cursor;
    for (const [s, c] of g.ranges) {
      newIndices.set(res.indices.subarray(s, s + c), cursor);
      cursor += c;
    }
    out.push({
      ...g.proto,
      firstIndex: start,
      indexCount: cursor - start,
      triangles: (cursor - start) / 3,
      useInstance: 0,
      instanceOffset: 0,
      instanceCount: 1,
    });
  }
  for (const d of instanced) out.push(d);
  res.indices = newIndices;
  return out;
}
